select ok(not exists(select 1 from audit.events where tenant_id=pg_temp.wid('tenant') and
 (before_context::text||after_context::text||metadata::text) like '%SYNTHETIC_PRIVATE%'),'AC-402 review and erasure audit remains redacted');
select ok(not exists(select 1 from core.command_receipts where tenant_id=pg_temp.wid('tenant') and response::text
 like '%SYNTHETIC_PRIVATE%'),'AC-402 all private receipts remain redacted');

