create function pg_temp.fail_hr_outbox() returns trigger language plpgsql as $$begin
 if new.command_id=pg_temp.wid('private-late') then raise exception using errcode='P0001',message='SYNTHETIC_HR_LATE_FAILURE';end if;
 return new;
end $$;
create trigger synthetic_hr_late_failure before insert on core.outbox_events for each row execute function pg_temp.fail_hr_outbox();
set local role authenticated;
select throws_ok($$select pg_temp.hr(pg_temp.hp()||jsonb_build_object('id',pg_temp.wid('third'),'employee_id',pg_temp.wid('third'),
 'revision_id',pg_temp.wid('third.private')),0,'private-late')$$,
 'P0001','SYNTHETIC_HR_LATE_FAILURE','AC-402 private late outbox failure aborts whole command');
reset role;
drop trigger synthetic_hr_late_failure on core.outbox_events;
select is((select count(*) from people_private.profiles where employee_id=pg_temp.wid('third')),0::bigint,'AC-402 late failure leaves no contact');
select is((select count(*) from audit.events where command_id=pg_temp.wid('private-late')),0::bigint,'AC-402 late failure leaves no audit');
select is((select count(*) from core.command_receipts where command_id=pg_temp.wid('private-late')),0::bigint,'AC-402 late failure leaves no receipt');
set local role authenticated;
