 encode(extensions.digest(convert_to((select body::text from people_private.profile_revisions where id=pg_temp.wid('third.private')),'UTF8'),'sha256'),'hex'),
 'AC-402 private digest is keyed rather than a reversible dictionary fingerprint');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
